static const Demo_VendingMachine_State kParent[Demo_VendingMachine_StateCount] = {
    Demo_VendingMachine_State_None,   /* Boot */
    Demo_VendingMachine_State_None,   /* Idle */
    Demo_VendingMachine_State_None,   /* Collecting */
    Demo_VendingMachine_State_None,   /* Ready */
    Demo_VendingMachine_State_None,   /* Dispensing */
    Demo_VendingMachine_State_Dispensing,   /* Dropping */
    Demo_VendingMachine_State_Dispensing,   /* Done */
};
static const unsigned char kRegionOf[Demo_VendingMachine_StateCount] =   /* region that contains the state */ {
    0,   /* Boot */
    0,   /* Idle */
    0,   /* Collecting */
    0,   /* Ready */
    0,   /* Dispensing */
    1,   /* Dropping */
    1,   /* Done */
};
static const unsigned char kFirstRegion[Demo_VendingMachine_StateCount] =   /* first own region */ {
    0,   /* Boot */
    0,   /* Idle */
    0,   /* Collecting */
    0,   /* Ready */
    1,   /* Dispensing */
    0,   /* Dropping */
    0,   /* Done */
};
static const unsigned char kRegionsOf[Demo_VendingMachine_StateCount] =   /* number of own regions */ {
    0,   /* Boot */
    0,   /* Idle */
    0,   /* Collecting */
    0,   /* Ready */
    1,   /* Dispensing */
    0,   /* Dropping */
    0,   /* Done */
};
static const char* const kStateNames[Demo_VendingMachine_StateCount] = {
    "Boot",   /* Boot */
    "Idle",   /* Idle */
    "Collecting",   /* Collecting */
    "Ready",   /* Ready */
    "Dispensing",   /* Dispensing */
    "Dropping",   /* Dropping */
    "Done",   /* Done */
};
static const char* const kEventNames[Demo_VendingMachine_EventCount] = {
    "Coin",
    "Select",
    "Cancel",
    "Collecting_After30000ms",
    "Dropping_After2000ms",
    "Completion",
};
static const Demo_VendingMachine_State kCompletion[Demo_VendingMachine_StateCount] =   /* state whose completion transitions fire when this state is reached */ {
    Demo_VendingMachine_State_Boot,   /* Boot */
    Demo_VendingMachine_State_None,   /* Idle */
    Demo_VendingMachine_State_None,   /* Collecting */
    Demo_VendingMachine_State_None,   /* Ready */
    Demo_VendingMachine_State_Dispensing,   /* Dispensing */
    Demo_VendingMachine_State_None,   /* Dropping */
    Demo_VendingMachine_State_Dispensing,   /* Done */
};

static size_t RegionOf(Demo_VendingMachine_State state) {
    return kRegionOf[state];
}

static size_t FirstRegionOf(Demo_VendingMachine_State state) {
    return kFirstRegion[state];
}

static size_t RegionsOf(Demo_VendingMachine_State state) {
    return kRegionsOf[state];
}

Demo_VendingMachine_State Demo_VendingMachine_ParentOf(Demo_VendingMachine_State state) {
    return state == Demo_VendingMachine_State_None ? Demo_VendingMachine_State_None : kParent[state];
}

const char* Demo_VendingMachine_StateName(Demo_VendingMachine_State state) {
    return state == Demo_VendingMachine_State_None ? "None" : kStateNames[state];
}

const char* Demo_VendingMachine_EventName(Demo_VendingMachine_Event event) {
    return kEventNames[event];
}

static void Trace(Demo_VendingMachine* m, Demo_VendingMachine_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

static void StartTimers(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    switch (state) {
        case Demo_VendingMachine_State_Collecting:
            ++m->timerGeneration[0];
            m->timerArmed[0] = true;
            m->hooks->StartTimer(m->context, Demo_VendingMachine_Event_Collecting_After30000ms, 30000u, m->timerGeneration[0]);
            break;
        case Demo_VendingMachine_State_Dropping:
            ++m->timerGeneration[1];
            m->timerArmed[1] = true;
            m->hooks->StartTimer(m->context, Demo_VendingMachine_Event_Dropping_After2000ms, 2000u, m->timerGeneration[1]);
            break;
        default:
            break;
    }
}

static void CancelTimers(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    switch (state) {
        case Demo_VendingMachine_State_Collecting:
            m->timerArmed[0] = false;
            m->hooks->CancelTimer(m->context, Demo_VendingMachine_Event_Collecting_After30000ms);
            break;
        case Demo_VendingMachine_State_Dropping:
            m->timerArmed[1] = false;
            m->hooks->CancelTimer(m->context, Demo_VendingMachine_Event_Dropping_After2000ms);
            break;
        default:
            break;
    }
}

static int TimerIndex(Demo_VendingMachine_Event event) {
    switch (event) {
        case Demo_VendingMachine_Event_Collecting_After30000ms:
            return 0;
        case Demo_VendingMachine_Event_Dropping_After2000ms:
            return 1;
        default:
            return -1;
    }
}

typedef void (*Handler)(Demo_VendingMachine* m);

static void Entry_Boot(Demo_VendingMachine* m) {
    m->hooks->selfTest(m->context);
}

static void Entry_Idle(Demo_VendingMachine* m) {
    m->hooks->showWelcome(m->context);
}

static void Entry_Collecting(Demo_VendingMachine* m) {
    m->hooks->showCredit(m->context);
}

static void Entry_Ready(Demo_VendingMachine* m) {
    m->hooks->showSelect(m->context);
}

static void Entry_Dispensing(Demo_VendingMachine* m) {
    m->hooks->openFlap(m->context);
}

static void Exit_Dispensing(Demo_VendingMachine* m) {
    m->hooks->closeFlap(m->context);
}

static const Handler kEntry[Demo_VendingMachine_StateCount] = {
    Entry_Boot,   /* Boot */
    Entry_Idle,   /* Idle */
    Entry_Collecting,   /* Collecting */
    Entry_Ready,   /* Ready */
    Entry_Dispensing,   /* Dispensing */
    NULL,   /* Dropping */
    NULL,   /* Done */
};
static const Handler kExit[Demo_VendingMachine_StateCount] = {
    NULL,   /* Boot */
    NULL,   /* Idle */
    NULL,   /* Collecting */
    NULL,   /* Ready */
    Exit_Dispensing,   /* Dispensing */
    NULL,   /* Dropping */
    NULL,   /* Done */
};
/* owner, initial target, initial action; row r - 1 describes region r */
static const struct { Demo_VendingMachine_State owner; Demo_VendingMachine_State initial; Handler action; } kRegions[Demo_VendingMachine_RegionCount - 1] = {
    { Demo_VendingMachine_State_Dispensing, Demo_VendingMachine_State_Dropping, NULL },   /* region 1 */
};

static void OnEntry(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    if (kEntry[state] != NULL) {
        kEntry[state](m);
    }
}

static void OnExit(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    if (kExit[state] != NULL) {
        kExit[state](m);
    }
}

static Demo_VendingMachine_State Innermost(const Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    while (state != Demo_VendingMachine_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Demo_VendingMachine_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void MarkCompletion(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    const Demo_VendingMachine_State owner = kCompletion[state];
    if (owner != Demo_VendingMachine_State_None) {
        m->pending[owner] = true;
    }
}

static void ExitState(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Demo_VendingMachine_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Demo_VendingMachine_Trace_Exit, Demo_VendingMachine_StateName(state));
    CancelTimers(m, state);
    OnExit(m, state);
    m->active[RegionOf(state)] = Demo_VendingMachine_State_None;
}

static void EnterState(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Demo_VendingMachine_Trace_Enter, Demo_VendingMachine_StateName(state));
    OnEntry(m, state);
    StartTimers(m, state);
}

static void EnterRegion(Demo_VendingMachine* m, size_t region) {
    if (kRegions[region - 1].action != NULL) {
        kRegions[region - 1].action(m);
    }
    EnterDown(m, kRegions[region - 1].owner, kRegions[region - 1].initial);
}

static void EnterDefault(Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
    if (RegionsOf(state) == 0) {
        MarkCompletion(m, state);
    }
}

static void EnterDown(Demo_VendingMachine* m, Demo_VendingMachine_State from, Demo_VendingMachine_State target) {
    Demo_VendingMachine_State state = target;
    Demo_VendingMachine_State next = Demo_VendingMachine_State_None;
    while (Demo_VendingMachine_ParentOf(state) != from) {
        next = state;
        state = Demo_VendingMachine_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Demo_VendingMachine_State_None) {
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target);
}

/* Event Coin in Idle: choice point. */
static bool Fire_1(Demo_VendingMachine* m) {
    if (m->hooks->hasEnoughCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents)) {
        Trace(m, Demo_VendingMachine_Trace_Transition, "Idle -> Ready (choice)");
        ExitState(m, Demo_VendingMachine_State_Idle);
        m->hooks->addCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents);
        EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Ready);
        return true;
    }
    Trace(m, Demo_VendingMachine_Trace_Transition, "Idle -> Collecting (choice)");
    ExitState(m, Demo_VendingMachine_State_Idle);
    m->hooks->addCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents);
    EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Collecting);
    return true;
}

/* Event Coin in Collecting: choice point. */
static bool Fire_2(Demo_VendingMachine* m) {
    if (m->hooks->hasEnoughCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents)) {
        Trace(m, Demo_VendingMachine_Trace_Transition, "Collecting -> Ready (choice)");
        ExitState(m, Demo_VendingMachine_State_Collecting);
        m->hooks->addCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents);
        EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Ready);
        return true;
    }
    Trace(m, Demo_VendingMachine_Trace_Transition, "Collecting -> Collecting (choice)");
    ExitState(m, Demo_VendingMachine_State_Collecting);
    m->hooks->addCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents);
    EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Collecting);
    return true;
}

/* Completion of Dispensing: choice point. */
static bool Fire_7(Demo_VendingMachine* m) {
    if (m->hooks->hasChange(m->context)) {
        Trace(m, Demo_VendingMachine_Trace_Transition, "Dispensing -> Idle (choice)");
        ExitState(m, Demo_VendingMachine_State_Dispensing);
        m->hooks->giveChange(m->context);
        EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Idle);
        return true;
    }
    Trace(m, Demo_VendingMachine_Trace_Transition, "Dispensing -> Idle (choice)");
    ExitState(m, Demo_VendingMachine_State_Dispensing);
    EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Idle);
    return true;
}

typedef bool (*GuardFn)(Demo_VendingMachine* m);

static void Transition_3(Demo_VendingMachine* m) {
    m->hooks->refund(m->context);
}

static bool Guard_4(Demo_VendingMachine* m) {
    return m->hooks->inStock(m->context, ((const Demo_VendingMachine_SelectArgs*)m->args)->item);
}

static void Transition_4(Demo_VendingMachine* m) {
    m->hooks->vend(m->context, ((const Demo_VendingMachine_SelectArgs*)m->args)->item);
}

static void Transition_5(Demo_VendingMachine* m) {
    m->hooks->refund(m->context);
}

static void Transition_6(Demo_VendingMachine* m) {
    m->hooks->addCredit(m->context, ((const Demo_VendingMachine_CoinArgs*)m->args)->cents);
}

typedef struct {
    Demo_VendingMachine_State source;
    Demo_VendingMachine_Event event;
    GuardFn guard;
    Handler action;
    Demo_VendingMachine_State target;   /* None for internal transitions */
    Demo_VendingMachine_State lca;
    GuardFn fire;       /* choice point: performs the whole transition */
    const char* name;
} TransitionRow;

/* source, event, guard, action, target, least common ancestor, choice, trace name */
static const TransitionRow kTransitions[9] = {
    { Demo_VendingMachine_State_Boot, Demo_VendingMachine_Event_Completion, NULL, NULL, Demo_VendingMachine_State_Idle, Demo_VendingMachine_State_None, NULL, "Boot -> Idle" },
    { Demo_VendingMachine_State_Idle, Demo_VendingMachine_Event_Coin, NULL, NULL, Demo_VendingMachine_State_None, Demo_VendingMachine_State_None, Fire_1, NULL },
    { Demo_VendingMachine_State_Collecting, Demo_VendingMachine_Event_Coin, NULL, NULL, Demo_VendingMachine_State_None, Demo_VendingMachine_State_None, Fire_2, NULL },
    { Demo_VendingMachine_State_Collecting, Demo_VendingMachine_Event_Collecting_After30000ms, NULL, Transition_3, Demo_VendingMachine_State_Idle, Demo_VendingMachine_State_None, NULL, "Collecting -> Idle" },
    { Demo_VendingMachine_State_Ready, Demo_VendingMachine_Event_Select, Guard_4, Transition_4, Demo_VendingMachine_State_Dispensing, Demo_VendingMachine_State_None, NULL, "Ready -> Dispensing" },
    { Demo_VendingMachine_State_Ready, Demo_VendingMachine_Event_Cancel, NULL, Transition_5, Demo_VendingMachine_State_Idle, Demo_VendingMachine_State_None, NULL, "Ready -> Idle" },
    { Demo_VendingMachine_State_Ready, Demo_VendingMachine_Event_Coin, NULL, Transition_6, Demo_VendingMachine_State_None, Demo_VendingMachine_State_None, NULL, "Ready (internal)" },
    { Demo_VendingMachine_State_Dispensing, Demo_VendingMachine_Event_Completion, NULL, NULL, Demo_VendingMachine_State_None, Demo_VendingMachine_State_None, Fire_7, NULL },
    { Demo_VendingMachine_State_Dropping, Demo_VendingMachine_Event_Dropping_After2000ms, NULL, NULL, Demo_VendingMachine_State_Done, Demo_VendingMachine_State_Dispensing, NULL, "Dropping -> Done" },
};

static bool TryRow(Demo_VendingMachine* m, const TransitionRow* row) {
    if (row->guard != NULL && !row->guard(m)) {
        return false;
    }
    if (row->fire != NULL) {
        return row->fire(m);
    }
    Trace(m, Demo_VendingMachine_Trace_Transition, row->name);
    if (row->target == Demo_VendingMachine_State_None) {
        if (row->action != NULL) {
            row->action(m);
        }
        return true;
    }
    Demo_VendingMachine_State root = row->source;
    while (Demo_VendingMachine_ParentOf(root) != row->lca) {
        root = Demo_VendingMachine_ParentOf(root);
    }
    ExitState(m, root);
    if (row->action != NULL) {
        row->action(m);
    }
    EnterDown(m, row->lca, row->target);
    return true;
}

static bool HandleEvent(Demo_VendingMachine* m, Demo_VendingMachine_State state, Demo_VendingMachine_Event event) {
    size_t i;
    for (i = 0; i < 9; ++i) {
        if (kTransitions[i].source == state && kTransitions[i].event == event && TryRow(m, &kTransitions[i])) {
            return true;
        }
    }
    return false;
}

static void RunCompletions(Demo_VendingMachine* m) {
    for (;;) {
        size_t index = 0;
        while (index < Demo_VendingMachine_StateCount && !m->pending[index]) {
            ++index;
        }
        if (index == Demo_VendingMachine_StateCount) {
            return;
        }
        m->pending[index] = false;
        if (m->active[RegionOf((Demo_VendingMachine_State)index)] == (Demo_VendingMachine_State)index) {
            HandleEvent(m, (Demo_VendingMachine_State)index, Demo_VendingMachine_Event_Completion);
        }
    }
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Demo_VendingMachine* m, Demo_VendingMachine_State state, Demo_VendingMachine_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Demo_VendingMachine_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Demo_VendingMachine* m, Demo_VendingMachine_Event event) {
    const int timer = TimerIndex(event);
    if (timer >= 0) {
        m->timerArmed[timer] = false;   /* a timer fires once */
    }
    Trace(m, Demo_VendingMachine_Trace_Event, Demo_VendingMachine_EventName(event));
    if (m->active[0] != Demo_VendingMachine_State_None && DispatchState(m, m->active[0], event)) {
        RunCompletions(m);
        return true;
    }
    Trace(m, Demo_VendingMachine_Trace_Ignored, Demo_VendingMachine_EventName(event));
    return false;
}

void Demo_VendingMachine_Init(Demo_VendingMachine* m, const Demo_VendingMachine_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Demo_VendingMachine_RegionCount; ++i) {
        m->active[i] = Demo_VendingMachine_State_None;
    }
    for (i = 0; i < Demo_VendingMachine_StateCount; ++i) {
        m->pending[i] = false;
    }
    for (i = 0; i < Demo_VendingMachine_TimerCount; ++i) {
        m->timerGeneration[i] = 0;
        m->timerArmed[i]      = false;
    }
    m->args = NULL;
}

void Demo_VendingMachine_Start(Demo_VendingMachine* m) {
    size_t i;
    if (m->timerArmed[0]) {
        m->timerArmed[0] = false;
        ++m->timerGeneration[0];
        m->hooks->CancelTimer(m->context, Demo_VendingMachine_Event_Collecting_After30000ms);
    }
    if (m->timerArmed[1]) {
        m->timerArmed[1] = false;
        ++m->timerGeneration[1];
        m->hooks->CancelTimer(m->context, Demo_VendingMachine_Event_Dropping_After2000ms);
    }
    for (i = 0; i < Demo_VendingMachine_RegionCount; ++i) {
        m->active[i] = Demo_VendingMachine_State_None;
    }
    for (i = 0; i < Demo_VendingMachine_StateCount; ++i) {
        m->pending[i] = false;
    }
    Trace(m, Demo_VendingMachine_Trace_Start, "VendingMachine");
    EnterDown(m, Demo_VendingMachine_State_None, Demo_VendingMachine_State_Boot);
    RunCompletions(m);
}

bool Demo_VendingMachine_Dispatch(Demo_VendingMachine* m, Demo_VendingMachine_Event event) {
    bool handled = false;
    if (event != Demo_VendingMachine_Event_Coin && event != Demo_VendingMachine_Event_Select && event != Demo_VendingMachine_Event_Completion) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
    }
    return handled;
}

bool Demo_VendingMachine_DispatchCoin(Demo_VendingMachine* m, int cents) {
    bool handled;
    Demo_VendingMachine_CoinArgs args;
    args.cents = cents;
    m->args = &args;
    handled = DispatchCore(m, Demo_VendingMachine_Event_Coin);
    m->args = NULL;
    return handled;
}

bool Demo_VendingMachine_DispatchSelect(Demo_VendingMachine* m, int item) {
    bool handled;
    Demo_VendingMachine_SelectArgs args;
    args.item = item;
    m->args = &args;
    handled = DispatchCore(m, Demo_VendingMachine_Event_Select);
    m->args = NULL;
    return handled;
}

bool Demo_VendingMachine_DispatchTimeout(Demo_VendingMachine* m, Demo_VendingMachine_Event timeout, unsigned generation) {
    bool handled = false;
    const int index = TimerIndex(timeout);
    if (index >= 0 && m->timerArmed[index] && m->timerGeneration[index] == generation) {
        m->args = NULL;
        handled = DispatchCore(m, timeout);
        m->args = NULL;
    }
    return handled;
}

Demo_VendingMachine_State Demo_VendingMachine_Current(const Demo_VendingMachine* m) {
    return Innermost(m, m->active[0]);
}

bool Demo_VendingMachine_IsIn(const Demo_VendingMachine* m, Demo_VendingMachine_State state) {
    return state != Demo_VendingMachine_State_None && m->active[RegionOf(state)] == state;
}

bool Demo_VendingMachine_IsFinished(const Demo_VendingMachine* m) {
    return ((void)m, false);
}

